76	    /**
77	     * Derive an owner's preferred contact channel from its stored contact details:
78	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
79	     */
80	    default String formatContactPreference(Owner owner) {
81	        if (owner == null) {
82	            return null;
83	        }
84	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
85	        return hasEmail ? "EMAIL" : "PHONE";
86	    }
